<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {ChevronDown,Plus,Check,LoaderCircle,Zap,RefreshCw,ExternalLink,KeyRound,Globe,ShieldCheck,Trash2} from 'lucide-vue-next'
import {api,type ModelProfile,type ProfileInput,type ModelConnection,type ModelRegistry,type SnapMindConfiguration} from '../api'
import {loadModels,modelRegistry,updateModels} from '../models'
import {tr,tx} from '../preferences'
import {native} from '../desktop'
import ConfigurationJson from './ConfigurationJson.vue'
import ModelSelect from './ModelSelect.vue'
interface Draft extends ProfileInput{apiKey:string;clearApiKey:boolean;showKey:boolean;busy:'save'|'test'|'models'|'clear'|null;error:string;message:string;modelNames:string[];fetched:boolean;manualModel:string;listVersion:number;result?:ModelConnection;baseline:string}
const rows=ref<ModelProfile[]>([]),drafts=ref<Record<string,Draft>>({}),expanded=ref<string|null>(null),loading=ref(true),loadError=ref(''),switching=ref(false)
const active=computed(()=>rows.value.find(p=>p.id===modelRegistry.value.activeId))
const savedKeyMask='••••••••••'
const configDocument=ref<SnapMindConfiguration>({schemaVersion:1,activeModelId:null,models:[]}),showKeys=ref(false),syncStatus=ref('saved'),syncError=ref('')
const syncTimers=new Map<string,ReturnType<typeof setTimeout>>()
let syncQueue=Promise.resolve(),disposed=false
const preview=computed<SnapMindConfiguration>(()=>{
 const models=rows.value.map(p=>{const d=drafts.value[p.id];const stored=configDocument.value.models.find(m=>m.id===p.id);const key=d?.clearApiKey?'':(d?.apiKey!==savedKeyMask?d?.apiKey.trim():'')||stored?.apiKey||(p.hasApiKey?'••••••••••':'');return {...stored,id:p.id,name:d?d.name:p.name,provider:p.vendor,baseUrl:d?.baseUrl.trim().replace(/\/+$/,'')||'',apiKey:!showKeys.value&&key?'••••••••••':key,model:d?.model.trim()||'',enabled:modelRegistry.value.activeId===p.id&&!dirty(p.id),vision:d?.vision||false}})
 return {schemaVersion:1,activeModelId:models.find(m=>m.enabled)?.id||null,models}
})
async function refreshDocument(){try{configDocument.value=await api.configuration(showKeys.value)}catch(e){syncError.value=e instanceof Error?e.message:String(e)}}
async function reveal(value:boolean){showKeys.value=value;await refreshDocument()}
function scheduleSync(id:string){const old=syncTimers.get(id);if(old)clearTimeout(old);syncStatus.value='pending';syncTimers.set(id,setTimeout(()=>{syncTimers.delete(id);enqueueSync(id)},650))}
function enqueueSync(id:string){syncQueue=syncQueue.then(()=>syncDraft(id)).catch(()=>{});return syncQueue}
async function syncDraft(id:string){const d=drafts.value[id];if(!d||!dirty(id)||!d.name.trim())return;if(d.busy&&d.busy!=='clear'&&!disposed){scheduleSync(id);return}const config=payload(d),version=signature(config);syncStatus.value='saving';syncError.value='';try{apply(await api.syncProfile(id,config));const current=drafts.value[id];current.baseline=version;if(signature(payload(current))===version){current.clearApiKey=false;current.apiKey=rows.value.find(p=>p.id===id)?.hasApiKey?savedKeyMask:'';current.baseline=signature(payload(current))}await refreshDocument();syncStatus.value=syncTimers.size?'pending':'saved';if(dirty(id)&&!disposed)scheduleSync(id)}catch(e){syncStatus.value='error';syncError.value=e instanceof Error?e.message:String(e)}}
async function flushSync(){for(const [id,timer] of syncTimers){clearTimeout(timer);syncTimers.delete(id);enqueueSync(id)}await syncQueue}
watch(()=>rows.value.map(p=>drafts.value[p.id]?signature(payload(drafts.value[p.id])):'').join('\n'),()=>{if(loading.value||disposed)return;for(const p of rows.value){if(drafts.value[p.id]&&dirty(p.id))scheduleSync(p.id)}},{flush:'post'})
function payload(d:Draft):ProfileInput{return {name:d.name,vendor:d.vendor,provider:d.provider,baseUrl:d.baseUrl.trim(),model:d.model.trim(),vision:d.vision,apiKey:d.apiKey&&d.apiKey!==savedKeyMask?d.apiKey:undefined,clearApiKey:d.clearApiKey}}
function signature(d:ProfileInput){return JSON.stringify(d)}
function createDraft(p:ModelProfile):Draft{const value={name:p.name,vendor:p.vendor,provider:'openai-compatible' as const,baseUrl:p.baseUrl,model:p.model,vision:p.vision,apiKey:p.hasApiKey?savedKeyMask:'',clearApiKey:false};return {...value,showKey:false,busy:null,error:'',message:'',modelNames:[],fetched:false,manualModel:p.model,listVersion:0,baseline:signature({...value,apiKey:undefined})}}
function dirty(id:string){return signature(payload(drafts.value[id]))!==drafts.value[id].baseline}
function requiresKey(p:ModelProfile){return p.vendor!=='custom'}
function canConnect(p:ModelProfile){const d=drafts.value[p.id];return !!d.baseUrl.trim()&&!d.clearApiKey&&!!(d.apiKey.trim()||p.hasApiKey)}
function apply(value:ModelRegistry,savedId?:string){updateModels(value);rows.value=[...value.profiles,...rows.value.filter(p=>!value.profiles.some(v=>v.id===p.id)&&!p.saved)];for(const p of rows.value){if(!drafts.value[p.id]||p.id===savedId){const previous=drafts.value[p.id];drafts.value[p.id]=createDraft(p);drafts.value[p.id].busy=previous?.busy||null}}}
async function load(){loading.value=true;loadError.value='';try{const value=await loadModels();rows.value=value.profiles;for(const p of rows.value)drafts.value[p.id]=createDraft(p);await refreshDocument()}catch{loadError.value=tr('无法加载模型配置，请检查本地服务。','無法載入模型設定，請檢查本機服務。','Unable to load models. Check the local service.')}finally{loading.value=false}}
function discardModelList(id:string){const d=drafts.value[id];if(!d)return;d.listVersion++;d.fetched=false;d.modelNames=[];resetFeedback(id)}
function discardModelLists(){for(const id of Object.keys(drafts.value))discardModelList(id)}
defineExpose({discardModelLists})
function toggle(id:string){if(expanded.value)discardModelList(expanded.value);discardModelList(id);expanded.value=expanded.value===id?null:id}
function resetFeedback(id:string){const d=drafts.value[id];d.error='';d.message='';d.result=undefined}
function credentialsChanged(id:string){const d=drafts.value[id];if(d.apiKey&&d.apiKey!==savedKeyMask)d.clearApiKey=false;discardModelList(id)}
async function clearKey(id:string){const d=drafts.value[id];if(d.busy||switching.value)return;d.apiKey='';d.clearApiKey=true;discardModelList(id);clearTimeout(syncTimers.get(id));syncTimers.delete(id);d.busy='clear';try{await enqueueSync(id);if(!drafts.value[id].clearApiKey){clearTimeout(syncTimers.get(id));syncTimers.delete(id);syncStatus.value=syncTimers.size?'pending':'saved';drafts.value[id].message=tr('API Key 已清除','API Key 已清除','API key cleared')}else drafts.value[id].error=syncError.value||tr('清除失败，请重试','清除失敗，請重試','Unable to clear the key. Please retry.')}finally{drafts.value[id].busy=null}}
function selectSavedKey(event:Event,id:string){if(drafts.value[id].apiKey===savedKeyMask)(event.target as HTMLInputElement).select()}
function restoreSavedKey(p:ModelProfile){const d=drafts.value[p.id];if(p.hasApiKey&&!d.clearApiKey&&!d.apiKey)d.apiKey=savedKeyMask}
function manual(id:string){const d=drafts.value[id];discardModelList(id);d.model=d.model||d.manualModel}
function chooseModel(id:string,value:string){drafts.value[id].model=value;resetFeedback(id)}
async function openPortal(p:ModelProfile,event:MouseEvent){if(!native)return;event.preventDefault();try{await api.openKeyPortal(p.vendor)}catch(e){drafts.value[p.id].error=e instanceof Error?e.message:String(e)}}
function add(){const id=crypto.randomUUID();const p:ModelProfile={id,name:tr('新模型配置','新模型設定','New model'),vendor:'custom',provider:'openai-compatible',baseUrl:'',model:'',hasApiKey:false,vision:false,saved:false};rows.value.push(p);drafts.value[id]=createDraft(p);expanded.value=id}
async function save(id:string){const d=drafts.value[id];d.busy='save';d.error='';d.message='';try{const ownTimer=syncTimers.get(id);if(ownTimer){clearTimeout(ownTimer);syncTimers.delete(id)}await flushSync();const config=payload(d);const value=await api.saveProfile(id,config);apply(value,id);await refreshDocument();syncStatus.value='saved';syncError.value='';drafts.value[id].message=tr('配置已保存','設定已儲存','Configuration saved')}catch(e){d.error=e instanceof Error?e.message:tr('保存失败，请重试','儲存失敗，請重試','Save failed. Please retry.')}finally{drafts.value[id].busy=null}}
async function test(id:string){const d=drafts.value[id];d.busy='test';resetFeedback(id);try{d.result=await api.testProfile(id,payload(d));if(d.result.ok)d.message=tr('连接成功','連線成功','Connected');else d.error=d.result.error||tr('连接失败','連線失敗','Connection failed')}catch(e){d.error=e instanceof Error?e.message:String(e)}finally{d.busy=null}}
async function fetchModels(id:string){const d=drafts.value[id],p=rows.value.find(p=>p.id===id);if(!p||d.busy||!canConnect(p))return;discardModelList(id);const version=d.listVersion;d.busy='models';try{const result=await api.fetchProfileModels(id,payload(d));if(disposed||expanded.value!==id||drafts.value[id]!==d||d.listVersion!==version)return;d.modelNames=result.models;d.manualModel=d.model;d.fetched=result.models.length>0;d.message=d.fetched?tr('已获取 ','已取得 ','Fetched ')+result.models.length+tr(' 个模型',' 個模型',' models'):tr('接口没有返回模型，仍可手动输入','介面沒有回傳模型，仍可手動輸入','No models returned; manual input remains available')}catch(e){if(!disposed&&drafts.value[id]===d&&d.listVersion===version)d.error=e instanceof Error?e.message:String(e)}finally{d.busy=null}}
async function enable(id:string){if(switching.value)return;switching.value=true;const target=modelRegistry.value.activeId===id?null:id;const d=drafts.value[id];d.error='';try{if(target)await flushSync();if(target&&dirty(id)){expanded.value=id;throw new Error(tr('请先保存修改，再启用此配置','請先儲存修改，再啟用此設定','Save your changes before enabling this model.'))}apply(await api.activateProfile(target));await refreshDocument()}catch(e){expanded.value=id;d.error=e instanceof Error?e.message:String(e)}finally{switching.value=false}}
onMounted(load)
onBeforeUnmount(()=>{disposed=true;for(const [id,timer] of syncTimers){clearTimeout(timer);syncTimers.delete(id);enqueueSync(id)}})
</script>
<template>
 <div class="model-profiles">
  <div class="model-profiles-heading"><div><h3>{{tr('模型与接口','模型與介面','Models & connections')}}</h3><p>{{tr('独立保存多个配置，同一时间只启用一个。','獨立儲存多個設定，同一時間僅啟用一個。','Save multiple configurations. Only one can be active at a time.')}}</p></div><button class="model-add" :disabled="loading||!!loadError||rows.length>=30" @click="add"><Plus :size="15"/>{{tr('添加配置','新增設定','Add model')}}</button></div>
  <div class="model-active-summary"><span class="model-active-dot" :class="{enabled:active}"/><span>{{active?tr('当前启用：','目前啟用：','Active: ')+active.name+' · '+active.model:tr('未启用模型','尚未啟用模型','No active model')}}</span><small>{{tr('保存不等于启用','儲存不等於啟用','Saving does not enable a model')}}</small></div>
  <p v-if="loading" class="model-profiles-status">{{tr('正在加载…','正在載入…','Loading…')}}</p><div v-else-if="loadError" class="model-profiles-status"><p role="alert">{{loadError}}</p><button @click="load">{{tx('重新加载')}}</button></div>
  <div v-else class="model-profile-list">
   <article v-for="p in rows" :key="p.id" class="model-profile" :class="{expanded:expanded===p.id,enabled:modelRegistry.activeId===p.id}" :data-profile-id="p.id">
    <div class="model-profile-row"><button class="model-profile-expand" :aria-label="tr('配置 ','設定 ','Configure ')+p.name" :aria-expanded="expanded===p.id" :aria-controls="'model-form-'+p.id" @click="toggle(p.id)"><span class="model-vendor-mark" :class="p.vendor"><Globe v-if="p.vendor==='custom'" :size="19"/><img v-else :src="'/model-logos/'+p.vendor+'.png'" alt="" aria-hidden="true" draggable="false"/></span><span class="model-profile-title"><strong>{{p.vendor==='custom'?tr(p.name,p.name,p.name):p.name}}</strong><small>{{p.saved?p.model:tr('点击展开配置','點擊展開設定','Click to configure')}}</small></span><span class="model-saved-tag" v-if="p.saved">{{tx('已保存')}}</span><ChevronDown class="model-expand-chevron" :size="17"/></button><div class="model-enable-control"><span>{{modelRegistry.activeId===p.id?tr('已启用','已啟用','Enabled'):tr('启用','啟用','Enable')}}</span><button role="switch" class="model-enable-switch" :aria-label="tr('启用 ','啟用 ','Enable ')+p.name" :aria-checked="modelRegistry.activeId===p.id" :disabled="switching||!p.saved||(requiresKey(p)&&!p.hasApiKey)||!!drafts[p.id].busy" @click="enable(p.id)"><span/></button></div></div>
    <Transition name="model-expand"><form v-if="expanded===p.id" :id="'model-form-'+p.id" class="model-profile-form" :aria-label="p.name+' '+tr('配置','設定','configuration')" @submit.prevent="save(p.id)">
     <fieldset :disabled="!!drafts[p.id].busy||switching" @input="resetFeedback(p.id)" @change="resetFeedback(p.id)">
      <label v-if="p.vendor==='custom'" class="profile-field full"><span>{{tr('配置名称','設定名稱','Configuration name')}}</span><input v-model="drafts[p.id].name" required maxlength="80" :aria-label="p.name+' '+tr('配置名称','設定名稱','name')"/></label>
      <label class="profile-field full"><span>{{tx('接口地址')}}</span><input v-model="drafts[p.id].baseUrl" @input="credentialsChanged(p.id)" required type="url" maxlength="2048" :aria-label="p.name+' '+tx('接口地址')" placeholder="https://api.example.com/v1" spellcheck="false"/><small v-if="p.vendor==='qwen'">{{tr('可替换为百炼控制台中对应区域的 API 地址。','可替換為百煉控制台中對應區域的 API 位址。','Use the endpoint for your workspace and region.')}}</small></label>
      <div class="profile-field full"><label :for="'key-'+p.id">API Key <small>{{p.hasApiKey?tx('已保存'):requiresKey(p)?tr('必填','必填','Required'):tx('可选')}}</small></label><div class="profile-key-input"><input :id="'key-'+p.id" v-model="drafts[p.id].apiKey" @input="credentialsChanged(p.id)" type="password" @focus="selectSavedKey($event,p.id)" @beforeinput="selectSavedKey($event,p.id)" @blur="restoreSavedKey(p)" maxlength="4096" autocomplete="off" :required="requiresKey(p)&&!p.hasApiKey&&!drafts[p.id].clearApiKey" :aria-label="p.name+' API Key'" :placeholder="p.hasApiKey?tx('留空保留已保存的密钥'):requiresKey(p)?tr('输入该服务的 API Key','輸入該服務的 API Key','Enter your provider API key'):tx('输入 API Key，本地无鉴权服务可留空')"/></div><div class="profile-key-actions"><a v-if="p.apiKeyUrl" class="profile-key-link" :href="p.apiKeyUrl" target="_blank" rel="noopener noreferrer" @click="openPortal(p,$event)"><KeyRound :size="13"/><span>{{tr('获取 API Key','取得 API Key','Get API key')}}</span><ExternalLink :size="12"/></a><button type="button" class="profile-clear-key" :disabled="!!drafts[p.id].busy||switching||!drafts[p.id].apiKey.trim()" @click="clearKey(p.id)"><LoaderCircle v-if="drafts[p.id].busy==='clear'" :size="13"/><Trash2 v-else :size="13"/>{{tr('清除 API Key','清除 API Key','Clear API key')}}</button></div></div>
      <div class="profile-field full"><div class="profile-model-heading"><label :for="'model-name-'+p.id">{{tx('模型名称')}}</label><div><button v-if="drafts[p.id].fetched" type="button" class="profile-manual" @click="manual(p.id)">{{tr('手动输入','手動輸入','Manual input')}}</button><button type="button" class="profile-fetch-models" :aria-busy="drafts[p.id].busy==='models'" :disabled="!!drafts[p.id].busy||!canConnect(p)" @click="fetchModels(p.id)"><RefreshCw :class="{rotating:drafts[p.id].busy==='models'}" :size="14"/>{{tr('获取模型列表','取得模型清單','Fetch models')}}</button></div></div><ModelSelect v-if="drafts[p.id].fetched" :id="'model-name-'+p.id" :model-value="drafts[p.id].model" :options="drafts[p.id].modelNames" :label="p.name+' '+tx('模型名称')" :disabled="!!drafts[p.id].busy||switching" @update:model-value="chooseModel(p.id,$event)"/><input v-else :id="'model-name-'+p.id" v-model="drafts[p.id].model" required maxlength="160" :aria-label="p.name+' '+tx('模型名称')" :placeholder="tx('填写服务提供的模型 ID')" spellcheck="false"/></div>
      <label class="profile-check full"><input type="checkbox" v-model="drafts[p.id].vision"/>{{tr('模型支持图片输入，允许发送截图进行处理','模型支援圖片輸入，允許傳送截圖進行處理','This model supports images; allow sending screenshots')}}</label>
     </fieldset>
     <div class="profile-feedback" v-if="drafts[p.id].error" role="alert">{{drafts[p.id].error}}</div><div class="profile-feedback success" v-else-if="drafts[p.id].message" role="status"><Check :size="14"/>{{drafts[p.id].message}}<span v-if="drafts[p.id].result?.modelAvailable===false">{{tr('此模型不在返回列表中，请核对名称','此模型不在回傳清單中，請核對名稱','Model not listed; check its ID')}}</span></div>

     <div v-if="drafts[p.id].result" class="profile-latency" :class="{failed:!drafts[p.id].result?.ok}" role="status"><Zap :size="14"/><span>{{tr('请求耗时','請求耗時','Request time')}}</span><strong>{{drafts[p.id].result?.latencyMs}}<small> ms</small></strong></div>
     <div class="profile-form-footer"><span><ShieldCheck :size="13"/>{{dirty(p.id)?tr('有未保存的修改','有未儲存的修改','Unsaved changes'):tr('密钥仅保存在本机','金鑰僅儲存在本機','Key stored on this device')}}</span><div><button type="button" class="profile-test" :disabled="!!drafts[p.id].busy||!canConnect(p)" @click="test(p.id)"><LoaderCircle v-if="drafts[p.id].busy==='test'" :size="15"/><Zap v-else :size="15"/>{{drafts[p.id].busy==='test'?tr('测速中…','測速中…','Testing…'):tr('测速','測速','Test latency')}}</button><button type="submit" class="profile-save" :disabled="!!drafts[p.id].busy||!drafts[p.id].model.trim()||!drafts[p.id].baseUrl.trim()"><LoaderCircle v-if="drafts[p.id].busy==='save'" :size="15"/><Check v-else :size="15"/>{{drafts[p.id].busy==='save'?tx('保存中…'):tx('保存配置')}}</button></div></div>
     <p class="profile-test-note">{{tr('测速显示接口请求耗时，不代表模型生成速度；不会自动启用。','測速顯示介面請求耗時，不代表模型生成速度；不會自動啟用。','Latency measures API response time, not generation speed. It does not enable a model.')}}</p>
    </form></Transition>
   </article>
  </div>
  <ConfigurationJson v-if="!loading&&!loadError" :value="preview" :show-keys="showKeys" :status="syncStatus" :error="syncError" @reveal="reveal"/>
 </div>
</template>
